(function(){
const button=document.querySelector('#toBeads'),canvas=document.querySelector('#canvas'),message=document.querySelector('#message');let destination=null,blobPromise=null,transferTimer=null;
button.onclick=()=>{if(!canvas.width||document.querySelector('#download').disabled){message.textContent='请先上传图片并生成效果。';return;}document.querySelector('#beadOverlay')?.remove();blobPromise=new Promise(resolve=>canvas.toBlob(resolve,'image/png'));const overlay=document.createElement('div');overlay.id='beadOverlay';Object.assign(overlay.style,{position:'fixed',inset:'0',zIndex:'1000',background:'#f6f5f1',display:'flex',flexDirection:'column'});const close=document.createElement('button');close.textContent='← 返回白物素材（拼豆工程请先保存）';Object.assign(close.style,{padding:'12px',border:'0',background:'#778b69',color:'white',cursor:'pointer',textAlign:'left'});close.onclick=()=>{if(!confirm('返回后此次拼豆编辑窗口会关闭。已保存工程吗？'))return;overlay.remove();destination=null;clearTimeout(transferTimer);};const iframe=document.createElement('iframe');iframe.title='拼豆与像素编辑器';Object.assign(iframe.style,{flex:'1',width:'100%',border:'0'});overlay.append(close,iframe);document.body.append(overlay);destination=iframe.contentWindow;iframe.src=button.dataset.target;message.textContent='正在把当前效果图送入拼豆编辑器…';clearTimeout(transferTimer);transferTimer=setTimeout(()=>{message.textContent='若图片没有自动载入，请下载PNG，再在拼豆编辑器点击「导入图片 / 图纸」。';},20000);};
window.addEventListener('message',async event=>{if(!destination||event.source!==destination||event.origin!==location.origin)return;if(event.data?.type==='whiteform-beads-ready'){const blob=await blobPromise;if(!blob){message.textContent='图片导出失败，请重新生成后再试。';return;}destination.postMessage({type:'whiteform-beads-image',blob,name:'白物效果图.png'},location.origin==='null'?'*':location.origin);}else if(event.data?.type==='whiteform-beads-loaded'){clearTimeout(transferTimer);message.textContent='已送入拼豆编辑器：设置行列和颜色数后转换，即可用画笔、填充、橡皮和吸管修改。';destination=null;blobPromise=null;}});
})();
